@RestController
@RequestMapping("/api/tasks")
class TaskController {

  @GetMapping
  List<Task> list(@RequestParam(defaultValue = "false") boolean doneOnly) { … }

  @GetMapping("/{id}")
  Task byId(@PathVariable Long id) { … }

  @PostMapping
  ResponseEntity<Task> create(@RequestBody NewTask body) {
    Task saved = service.create(body);
    return ResponseEntity
        .created(URI.create("/api/tasks/" + saved.id()))
        .body(saved);
  }

  @DeleteMapping("/{id}")
  ResponseEntity<Void> delete(@PathVariable Long id) {
    service.delete(id);
    return ResponseEntity.noContent().build();
  }
}

@Service
class TaskService {

  private final TaskRepository repository;

  TaskService(TaskRepository repository) {   // no @Autowired needed
    this.repository = repository;
  }

  Task complete(Long id) {
    Task task = repository.findById(id)
        .orElseThrow(() -> new TaskNotFoundException(id));
    task.setDone(true);
    return repository.save(task);
  }
}

record NewTask(
    @NotBlank(message = "title must not be blank")
    @Size(max = 120, message = "title must be at most 120 characters")
    String title,

    @Size(max = 2000)
    String description) {}

@RestControllerAdvice
class ApiErrors {

  @ExceptionHandler(MethodArgumentNotValidException.class)
  ProblemDetail invalid(MethodArgumentNotValidException ex) {
    ProblemDetail body = ProblemDetail.forStatusAndDetail(
        HttpStatus.BAD_REQUEST, "One or more fields are invalid.");
    body.setTitle("Validation failed");
    Map<String, String> errors = new LinkedHashMap<>();
    for (FieldError e : ex.getBindingResult().getFieldErrors()) {
      errors.put(e.getField(), e.getDefaultMessage());
    }
    body.setProperty("errors", errors);
    return body;
  }

  @ExceptionHandler(TaskNotFoundException.class)
  ProblemDetail notFound(TaskNotFoundException ex) {
    return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, ex.getMessage());
  }
}

@Entity
class Task {

  @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
  private Long id;

  @Column(nullable = false, length = 120)
  private String title;

  private String description;
  private boolean done;

  protected Task() { }            // JPA needs a no-arg constructor

  Task(String title, String description) {
    this.title = title;
    this.description = description;
  }
  // getters / setters
}

interface TaskRepository extends JpaRepository<Task, Long> {
  List<Task> findByDoneTrue();
  List<Task> findByTitleContainingIgnoreCase(String fragment);
}

class TaskServiceTest {

  private final TaskRepository repository = mock(TaskRepository.class);
  private final TaskService service = new TaskService(repository);

  @Test
  void completing_a_missing_task_is_rejected() {
    when(repository.findById(7L)).thenReturn(Optional.empty());

    assertThrows(TaskNotFoundException.class, () -> service.complete(7L));
  }
}

